SET search_path TO payments; CREATE TABLE IF NOT EXISTS subscriptions (id UUID PRIMARY KEY, user_id UUID NOT NULL, plan VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, amount DECIMAL(15,2) NOT NULL, start_date TIMESTAMP NOT NULL, end_date TIMESTAMP NOT NULL, payment_method VARCHAR(100), auto_renew BOOLEAN DEFAULT TRUE, cancelled_at TIMESTAMP, cancellation_reason VARCHAR(500), max_vendor_views_per_month INTEGER, max_saved_lands INTEGER, can_access_premium_listings BOOLEAN, can_contact_vendor_directly BOOLEAN, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
